const ARQUIVO = "app/(app)/agenda/components/AgendaCalendar.tsx";

console.log("\nCorrecao - rolagem da agenda revertida + espaco no final\n");

if (!existsSync(ARQUIVO) || !existsSync("package.json")) {
  console.error("ERRO: rode este script na pasta raiz do projeto (a mesma do package.json).\n");
  process.exit(1);
}

